import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.Pp2klvcf.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/evolution/index.md","filePath":"en/evolution/index.md","lastUpdated":1788681727000}'),i={name:"en/evolution/index.md"};function r(o,e,p,c,d,l){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Fast-Vue3 maintains two parallel branches. <code>polyrepo</code> is a single Vue application with build-time UI selection. <code>main</code> is a pnpm/Turbo workspace with independent admin and portal applications.</p><p>apps/ contains independently runnable admin and portal templates. packages/ contains request, stores, preferences, styles, layout, access, locales and shared contracts. internal/ contains Vite, TypeScript and lint tooling. scripts/ contains vsh and turbo-run.</p><p>workspace:* links local packages; catalog: centralizes dependency versions. Turbo dev/build depend on upstream ^build. The Vite config package loads dist/index.mjs, so tool changes require stub/build.</p><p>Use pnpm create-app to generate an admin or site app and add root dev/build scripts. Main’s request API returns an Axios instance from createHttpClient; createRequest unwraps result. Do not assume it implements polyrepo’s ApiError/204 handling.</p><p><a href="/fast-vue3-site/en/guide/getting-started">Choose a branch</a></p>',6)])])}const h=t(i,[["render",r]]);export{m as __pageData,h as default};
